const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createAccountUI({cloud,context,modal,handlers,go,toast}){
 let info=null,tab='invite',invitation=null,request=0,busy=false,pendingPair=null;const key='echoo-invitation-'+cloud.session.username;
 try{const v=JSON.parse(sessionStorage.getItem(key));if(typeof v?.code==='string'&&/^[a-f0-9]{36}$/.test(v.code)&&v.expires>Date.now())invitation=v}catch{}
 const button=(action,label,primary=false)=>'<button type="button" data-do="'+action+'" class="pill '+(primary?'primary':'')+'">'+label+'</button>';
 function result(message){const e=document.querySelector('#account-result');if(e)e.textContent=message}
 function show(){if(!info)return;const paired=info.paired;modal('settings','Echoo','账号与配对','<p class="account-name">'+esc(info.username)+'</p>'+(paired?'<section class="account-pair"><small>已唯一绑定</small><h3>♡ '+esc(info.partner||'另一位住户')+'</h3>'+button('account-visit','去对方的星球',true)+'<button type="button" data-do="account-unpair" class="account-unpair">解除绑定</button></section>':'<section class="account-pair"><h3>连接另一个人</h3><div class="account-tabs">'+['invite','join'].map(id=>'<button type="button" data-do="account-tab" data-tab="'+id+'" aria-pressed="'+(tab===id)+'">'+(id==='invite'?'邀请对方':'我有配对码')+'</button>').join('')+'</div>'+(tab==='invite'?(invitation&&invitation.expires>Date.now()?'<div class="cloud-code">'+esc(invitation.code)+'</div><p class="subtle">有效至 '+new Date(invitation.expires).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})+'</p><div class="form-actions">'+button('account-copy','复制配对码',true)+button('account-replace','换一个配对码')+'</div>':'<p class="subtle">把配对码发给已注册的对方。</p>'+(info.invitationExpires>Date.now()?button('account-replace','换一个配对码',true):button('account-generate','生成配对码',true))):'<form id="account-pair-form"><label for="account-pair-code">对方生成的配对码</label><input id="account-pair-code" name="code" required maxlength="128" autocapitalize="none" autocorrect="off" spellcheck="false" placeholder="粘贴 36 位配对码"><p class="subtle">确认对方账号后，才会绑定。</p><button class="pill primary" type="submit">连接星球</button></form>')+'</section>')+'<p id="account-result" role="status"></p>'+'<details class="account-details"><summary>更多设置</summary><div class="form-actions">'+button('weread-settings','微信读书')+button('export-all','导出手账')+button('account-history','过去的记录')+button('logout','退出登录')+'</div><a href="/food-credits.html" target="_blank" rel="noopener">模型鸣谢</a> · <a href="/sleep-credits.html" target="_blank" rel="noopener">声音与词库鸣谢</a></details>');
 const pair=document.querySelector('#account-pair-form');if(pair)pair.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const b=pair.querySelector('button');b.disabled=true;result('正在连接…');try{const code=pair.elements.code.value.trim(),r=await cloud.previewPair(code);if(!r)result(cloud.lastActionError||'连接未完成，请重试');else{pendingPair={code,...r};modal('account-confirm','Echoo','连接这个人？','<div class="account-pair"><h3>'+esc(r.username)+'</h3><p class="subtle">绑定后，可以互访和分享日常。</p></div><div class="form-actions">'+button('account-keep','返回')+button('account-connect','确认绑定',true)+'</div><p id="account-result" role="status"></p>')}}finally{busy=false;b.disabled=false}};

 }
 async function open(){const token=++request;modal('settings','Echoo','账号与配对','<p class="subtle">正在读取账号…</p>');try{const next=await cloud.accountInfo();if(token!==request||context().panel!=='settings'||!next)return;info=next;if(info.paired||invitation?.expires!==info.invitationExpires){invitation=null;try{sessionStorage.removeItem(key)}catch{}}show()}catch(e){if(token===request&&context().panel==='settings')modal('settings','Echoo','账号与配对','<p role="alert">'+esc(e.message)+'</p>'+button('account-open','重试'))}}
 async function generate(){if(busy)return;busy=true;result('正在生成…');try{const r=await cloud.invite();if(!r){result(cloud.lastActionError);return}invitation=r;try{sessionStorage.setItem(key,JSON.stringify(r))}catch{}if(['settings','account-replace'].includes(context().panel)){tab='invite';show()}}finally{busy=false}}
 handlers['account-open']=open;handlers['account-tab']=b=>{if(busy)return;tab=b.dataset.tab;show()};handlers['account-generate']=generate;
 handlers['account-copy']=async()=>{if(!invitation||invitation.expires<=Date.now()){invitation=null;show();result('配对码已过期，请重新生成');return}try{await navigator.clipboard.writeText(invitation.code);result('已复制，请发给对方')}catch{result('请长按上方配对码复制')}};
 handlers['account-replace']=()=>modal('account-replace','Echoo','换一个配对码？','<p>原配对码将立即失效。请把新码重新发给对方。</p><div class="form-actions">'+button('account-keep','保留原码')+button('account-generate','生成新码',true)+'</div><p id="account-result" role="status"></p>');handlers['account-keep']=show;
 handlers['account-visit']=()=>go(1-context().actor);
 handlers['account-unpair']=()=>modal('account-unpair','Echoo','解除这段绑定？','<p>双方将停止互访，共享内容不再对彼此可见。各自星球和物品保留。共同记录放进「过去的记录」，不会分享给新伴侣。</p><div class="form-actions">'+button('account-keep','保持绑定',true)+button('account-confirm-unpair','确认解绑')+'</div><p id="account-result" role="status"></p>');
 handlers['account-confirm-unpair']=async b=>{if(busy)return;busy=true;b.disabled=true;try{await cloud.unpair();result(cloud.lastActionError||'正在更新…')}finally{busy=false;b.disabled=false}};
 handlers['account-connect']=async b=>{if(busy||!pendingPair)return;busy=true;b.disabled=true;try{const r=await cloud.pair(pendingPair.code,pendingPair.id);if(!r)result(cloud.lastActionError)}finally{busy=false;b.disabled=false}};
 handlers['account-history-export']=async()=>{try{const data=await cloud.history(),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='echoo-past-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}};
 handlers['account-history']=async()=>{modal('account-history','Echoo','过去的记录','<p>正在读取…</p>');try{const data=await cloud.history();if(context().panel!=='account-history')return;modal('account-history','Echoo','过去的记录',data.archives.length?'<p class="subtle">仅自己可见，不会分享给新伴侣。</p>'+button('account-history-export','导出这些记录')+data.archives.map(a=>'<details class="account-details"><summary>'+new Date(a.created).toLocaleString('zh-CN')+'</summary>'+[...a.state.events,...a.state.notes].map(e=>'<article><h4>'+esc(e.title)+'</h4><p>'+esc(e.body)+'</p></article>').join('')+'<p>'+a.media.length+' 件书架与唱片记录</p></details>').join(''):'<p class="subtle">还没有过去的记录。</p>');}catch(e){result(e.message)}};
 return {open};
}
